def _reject_duplicate_json_pairs(pairs):
    """``object_pairs_hook`` that rejects duplicate JSON object keys."""
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = value
    return result


